import { HistoricalDocument } from '../../types';

export const ordenacoesLivro1TitulosXxiAXxx: HistoricalDocument = {
  id: 'ordenacoes-livro-1-titulos-xxi-a-xxx',
  title: 'Ordenações Filipinas — Títulos XXI a XXX',
  subtitle: 'Do Meirinho, que anda na Corte',
  date: '1603',
  era: 'Idade Moderna',
  language: 'Português',
  description: `Títulos XXI a XXX do Livro Primeiro das Ordenações Filipinas: de "Do Meirinho, que anda na Corte" a "Dos Porteiros da Chancellaria do Reino e da Casa da Supplicação".`,
  parentCollectionId: 'ordenacoes-livro-1',
  sections: [
    {
      id: 'titulo-xxi',
      title: `XXI. Do Meirinho, que anda na Corte`,
      type: 'articles',
      articles: [
        { id: 'of1-txxi-preambulo', number: 'Preâmbulo', text: `O Meirinho Mór ha de pôr de sua mão hum Meirinho, que ande continuadamente na Corte, para alevantar as forças e semrazões, que nella forem feitas, e prender os malfeitores, e fazer as cousas conteidas neste Titulo. E este deve ser Scudeiro de boa linhagem, e conhecido por bom, e posto per nossa auctoridade, e de que tenhamos conhecimento, para o approvar para servir o dito Officio.` },
        { id: 'of1-txxi-1', number: '1', text: `O Meirinho da Corte prenderá os que achar nos maleficios e arroidos, ou lhe for requerido por qualquer pessoa nos ditos arroidos. E antes que os leve á cadea, leval-os-ha perante o Corregedor. E geralmente prenderá todos aquelles, que per o Corregedor lhe for mandado, ou per quaesquer Officiaes nossos, per Alvarás per elles assinados, no que a seus Officios pertencer, e poder tiverem para mandar prender.` },
        { id: 'of1-txxi-2', number: '2', text: `Item, será obrigado correr de noite o lugar, em que Nós stivermos, áquellas horas, que per o Corregedor da Corte lhe for ordenado, e com elle irá sempre hum Scrivão, que para isso tiver nossa Provisão, e não outro: salvo sendo o dito Scrivão impedido.` },
        { id: 'of1-txxi-3', number: '3', text: `E irá fazer execuções de penhora, quando lhe for mandado pelo Corregedor, ou per outro algum Julgador com o Porteiro e Scrivão. E levará o Meirinho de cada penhora e execução, sendo na cidade de Lisboa e seus arrabaldes, trezentos réis á custa da parte condenada para elle e para seus homens: comtanto que os ditos trezentos réis não excedam a vintena parte; mas não haverá nunca menos de cento e cincoenta réis, as duas partes para si, e a terceira parte para seus homens. E quando for fazer a dita diligencia fóra do lugar e seus arrabaldes, levará para si e para seus homens o que lhe for arbitrado pelo Regedor com dous Desembargadores em Relação, havendo respeito ao trabalho, que nisso levarem. O que tudo assi haverá á custa das partes condenadas, ou contra quem se fizerem as taes diligencias. O qual salario não levará ás partes, sem primeiro com effeito ter feitas as ditas penhoras. E todo o sobredito se guardará nas execuções, que forem feitas pelos Alcaides na cidade de Lisboa.` },
        { id: 'of1-txxi-4', number: '4', text: `E o dito Meirinho da Corte e os Alcaides e seus homens, sendo requeridos de nossa parte pelo Sollicitador dos feitos da Fazenda, assi para prender alguma pessoa, que os Officiaes della, ou da Relação mandarem prender, mostrando-lhe mandados para isso, ou para chegarem algumas testemunhas, que em nossos feitos hajam de testemunhar, ou fazer outras diligencias, o farão logo, e cumprirão com brevidade o que lhe pelo dito Sollicitador for requerido, sem por isso levarem salario algum.` },
        { id: 'of1-txxi-5', number: '5', text: `Item, o Meirinho he obrigado a defender os Regatães, e assi todos aquelles, que à Corte trouxerem os mantimentos, que lhe não façam força em tomarem o seu contra suas vontades; e fazendo-lha alguns, acudirá a isso como for justiça; e não o fazendo assi, pagal-o-ha per sua fazenda: salvo se a pessoa, que assi forçosamente o sobredito fizer, for tal, que elle per si o não possa remediar, porque então elle o fará saber ao Corregedor da Corte, para nisso prover.` },
        { id: 'of1-txxi-6', number: '6', text: `Outrosi mandamos, que nenhum dos Meirinhos da Corte, nem das Correições e Ouvidorias, nem homem seu, possa encoimar sem hum homem bom Juramentado, para isso elegido pelos Juizes e Officiaes do Concelho, e fazendo-o sem o dito homem bom, não lhe será dado fé.` },
        { id: 'of1-txxi-7', number: '7', text: `E nenhum dos homens dos Meirinhos, Alcaides, nem dos Corregedores das Comarcas, Ouvidores e Juizes de fóra terá taverna: e tendo-a, seja açoutado publicamente com baraço e pregão, e pague trinta cruzados, ametade para quem o accusar, e outra para os captivos.

Direitos, que póde levar.` },
        { id: 'of1-txxi-8', number: '8', text: `O Meirinho Mór, ou aquelle, que na Corte andar por elle, levará de todos os Regatães, que na Corte andarem, de cada carrega de pescadas, que a ella trouxerem a vender, huma pescada até quatro carregas; e se mais carregas trouxer de pescadas, ou de outro pescado, por essa vez não levará mais.` },
        { id: 'of1-txxi-9', number: '9', text: `De Grandos, Toninhas, e de outro pescado grande, assi como Corvinas, Outrenes, e outro semelhante, levará huma posta do lombo de hum palmo, de cada carrega até quatro carregas, e mais não hum. E se não for carrega, assi como de hum, dous até tres peixes, não levará cousa alguma. E mais levará seu direito do outro pescado miudo, se com elle o trouxerem, até quatro carregas, como dito he.` },
        { id: 'of1-txxi-10', number: '10', text: `Dos Saveis levará hum de cada carrega, até quatro carregas.` },
        { id: 'of1-txxi-11', number: '11', text: `Dos Vesugos, Mugens, e outro qualquer pescado miudo, levará huma duzia de cada carrega, até quatro carregas. E se for peixe maior, meia duzia.` },
        { id: 'of1-txxi-12', number: '12', text: `De Arraias, Canejas, ou Cações pequenos, levará de cada carrega hum peixe, até quatro carregas. E se forem grandes, levará huma posta, assi como dito he dos Congros e Toninhas.` },
        { id: 'of1-txxi-13', number: '13', text: `Se trouxerem hum Solho, e o venderem às postas, levará huma posta: e se o levarem junto para Nós, ou para alguma pessoa, não levará cousa alguma. E postoque tragam mais Solhos, não levará mais de huma posta de cada carrega, até quatro.` },
        { id: 'of1-txxi-14', number: '14', text: `De Linguados, Salmonetes, Lampreas, peixe scolar não leve cousa alguma.` },
        { id: 'of1-txxi-15', number: '15', text: `Do vinho levará huma canada de huma carrega, até quatro carregas.` },
        { id: 'of1-txxi-16', number: '16', text: `De pannos, calçado, trigo, fructas, e de outros quaesquer mantimentos, que trouxerem, não levará cousa alguma.` },
        { id: 'of1-txxi-17', number: '17', text: `Item, dos que vierem fóra do lugar e termo, onde Nós stivermos, e for per constrangimento, e trouxerem cevada, levará de cada carrega huma quarta, até quatro carregas, e dos outros mantimentos não leve cousa alguma: e isso mesmo não levará cousa alguma dos que vierem de fóra per sua vontade, nem dos que vierem da cidade, villa, ou termo a dentro, postoque venham per constrangimento.` },
        { id: 'of1-txxi-18', number: '18', text: `E dos Regatães e Carniceiros, que na Corte andarem (não sendo nosso Carniceiro, ou da Rainha, ou do Principe, ou dos Infantes), levará de cada Boi, ou Vacca hum lombo; e de cada Porco hum lombo dos pequenos; e de cada Carneiro as tubaras.` },
        { id: 'of1-txxi-19', number: '19', text: `E faça de tal maneira, que os direitos, que ha de haver dos Carniceiros, e de outras pessoas, os requeira no dito dia, ou até o outro, a mais tardar. E não o fazendo, os não possa mais demandar, nem seja sobre isso ouvido em Juizo.` },
        { id: 'of1-txxi-20', number: '29', text: `Item, dos da villa e termo, onde Nós formos, e assi de todos os que á Corte trouxerem de suas vontades a vender pão, vinho, carnes, pescado, e outros quaesquer mantimentos, não levará cousa alguma.` },
        { id: 'of1-txxi-21', number: '21', text: `E emquanto Nós stivermos em a cidade de Lisboa, ou em seu termo, o Meirinho não levará cousa alguma, porque atégora o não levaram: salvo dos Regatães da Corte, se ahi quizerem star e vender.` },
        { id: 'of1-txxi-22', number: '22', text: `Item, o Meirinho da Corte levará penas de excommungados, e dos barregueiros casados e de suas barregãs, e mancebas dos Clerigos, Frades e Religiosos, que prender e accusar. E as coimas das bestas, que achar em dano, e das mulas e dos cavallos menos de marca, quando forem defesos e todas as outras penas, que ha de levar, segundo as Ordenações, que expressamente mandam, que seiam para o Meirinho: e assi as armas, que tomar na Corte. As quaes penas de armas, mulas e coimas acima ditas se partirão per esta maneira: levará o Meirinho ametade; e seus homens, que com elle forem, ou as acharem, a outra ametade. E não leve mais direitos do que nesta Ordenação he conteúdo. E faca as cousas, como lhe he mandado, sob pena de perder o Officio; e mais haverá a pena, que per nossa Ordenação he posta áquelles, que levam mais do conteúdo em seu Regimento.` },
        { id: 'of1-txxi-23', number: '23', text: `Item, onde quer que Nós formos, sejam dadas pousadas ao Meirinho para elle e seus homens, e para os Regatães e Carniceiros, que na Corte andarem, e elle lhe dê as pousadas, como vir que cumpre.` },
      ],
    },
    {
      id: 'titulo-xxii',
      title: `XXII. Do Meirinho das Cadêas`,
      type: 'articles',
      articles: [
        { id: 'of1-txxii-preambulo', number: 'Preâmbulo', text: `O Meirinho das Cadêas ha de star na Relação todos os dias, que se fizer prestes para fazer o que cumprir a seu Officio, e lhe mandarem, de prender e trazer presos, e qualquer outra cousa, que a bem de justiça cumprir. E haverá mantimento para si e para doze homens, que com elle andarão, para fazerem o que cumprir a seu Officio.` },
        { id: 'of1-txxii-1', number: '1', text: `E quando for occupado em alguma cousa, que cumpra a bem de justiça, ou per nosso mandado, ou do Regedor, ou dos Corregedores da Corte, deixar de vir á Relação, deixará nella cada dia dous homens seus, os quaes starão nella, até se acabarem as audiencias todas, que se fazem á saida da Relação. E o Meirinho, que sem o tal mandado deixar de star na Relação, como dito he, ou quando nella não stiver, por ter a sobredita licença, não deixar os ditos homens, perderá dous tostões por cada vez, os quaes lhe serão descontados de seu mantimento. Porém, no caso que elle deixar os homens, e elles, ou cada hum delles se for antes das audiencias acabadas, o Meirinho fará disso certo ao Regedor, o qual mandará descontar do mantimento dos ditos homens, ou de cada hum delles os duzentos réis. E mandamos a todos os Desembargadores, que fizerem as audiencias, que cada vez que não acharem na audiencia ao Meirinho, ou os dous homens, o façam logo saber ao Regedor, para os punir, como dito he.` },
        { id: 'of1-txxii-2', number: '2', text: `E o Meirinho e seus homens hão de levar os presos ás audiencias dos Corregedores e Ouvidores, ou quando per cada hum delles lhe for mandado. E ha de requerer ao Carcereiro, que ponha boa guarda nos presos. E não o fazendo, o dirá aos Corregedores, para que o constranjam, e provejam de maneira, que seiam bem guardados; e de outro modo Nós castigaremos aquelle, por cuja negligencia se seguir algum dano á Justiça. E ha de prender e correr de noite, na forma que fica dito no Titulo 21: Do Meirinho, que anda na Corte (§§ 1 e 2).` },
        { id: 'of1-txxii-3', number: '3', text: `E fará as diligencias, que lhe forem requeridas pelo Sollicitador da Fazenda, sem por isso levar salario, como se disse no Titulo 21: Do Meirinho, que anda na Corte (§ 4).` },
        { id: 'of1-txxii-4', number: '4', text: `E será Juiz das mulheres solteiras, que andam na Corte, convém a saber, de roídos, que humas com outras tiverem de palavras sómente: e levará de cada huma dellas quatro réis cada sabbado, porquanto ella ha de mandar varrer a casa das Audiencias dos Corregedores da Corte, que ellas haviam de varrer, segundo costume antigo.` },
        { id: 'of1-txxii-5', number: '5', text: `E ha de haver dos homens, que per Justiça morrerem, huma carceragem do monte mór, por cada huma, que for justiçado. E assi levará a parte das carceragens, que se dirá no Titulo 34: Das carceragens da Corte (§ 5).` },
        { id: 'of1-txxii-6', number: '6', text: `E acontecendo algum caso, por que a Casa da Supplicação se saia de Lisboa, irá com a cadea da Corte, quando for de hum lugar para outro, para fazer receber e aprisoar os presos nos lugares, onde chegar. E quando a cadea houver de partir, lhe darão tanta gente, que baste, postoque haja bolsa, e postoque tenham privilegio para não receberem presos, por quanto os taes privilegios se não entendem, quando a cadea da Corte vai per a terra privilegiada. E terá cuidado de levar duas vezes em cada hum dia per si, ou per seus homens todos os presos fazer suas necessidades aos lugares para isso assirrados, quando não houver outro remedio para sua ida fóra se poder escusar. E não consentirá, que os presos sejam mal tratados, nem lhe seja feita semrazão per pessoa alguma.` },
      ],
    },
    {
      id: 'titulo-xxiii',
      title: `XXIII. Do Scrivão dos feitos del Rei`,
      type: 'articles',
      articles: [
        { id: 'of1-txxiii-preambulo', number: 'Preâmbulo', text: `O Scrivão dos nossos feitos porá boa diligencia em os guardar, e fará rol delles, e dal-o-ha ao nosso Procurador; e se vir, que o Juiz, ou Procurador não são diligentes ao desembargar e requerer, faça outro rol delles, pondo o dia, em que forem começados, se vierem per appellação, e o dia, que á Corte chegarem; e dal-o-ha a Nós, ou ao Regedor, para o ver, e fazer desembargar aquelles, que entender que cumpre, e reprehender aquelles por cuja negligencia forem retardados.` },
        { id: 'of1-txxiii-1', number: '1', text: `Item, fará com diligencia todas as Cartas de quaesquer desembargos, que saírem para se fazerem quaesquer diligencias, ou para se tirarem inquirições em nossos feitos, e as dará a assinar ao Juiz delles, per quem houverem de ser assinadas. E tanto que forem assinadas, as entregará ao nosso Sollicitador, para as fazer sellar. E como lhe forem dadas, o dito Sollicitador e o nosso Procurador farão fazer as ditas diligencias, como nas Cartas for conteúdo.` },
        { id: 'of1-txxiii-2', number: '2', text: `E como o feito for desembargado per sentença definitiva, fará logo a sentença, e se for dada por nossa parte, a fará assinar e passar pela Chancellaria. E tanto que for passada, será trasladada em hum livro, em boa letra; e depois que for trasladada e concertada, dal-a-ha ao nosso Procurador da Coroa, ou da Fazenda, segundo o caso for, aos quaes mandamos, que façam fazer per ella execução. E depois de feita, torne-se a sentença ao Scrivão, que guardará bem as ditas scripturas e feitos desembargados. E as sentenças, depois de executadas, dará ao Guarda Mór da Torre do Tombo, para nella se lançarem com as outras nossas scripturas; ao qual mandamos, que as tome e ponha em hum armario, para isto ordenado na dita Torre. E depois que o dito livro for acabado, será posto na dita Torre no dito armario, e far-se-ha outro livro como o primeiro, em que registre as sentenças, que depois forem dadas, e scripturas. E como for acabado, faça-o encadernar e ajuntar com o outro. E assi se fará ao diante, sendo acabados quaesquer dos outros livros, os quaes livros e sentenças, nelles registradas, mandamos, que façam fé. E o dito Scrivão seja diligente em todas estas cousas, em modo que por sua culpa se não percam feitos alguns, ou scripturas: e que os ditos registros se guardem, como dito he, sob pena de privação do Officio, e de lho stranharmos, como houvermos por bem.` },
        { id: 'of1-txxiii-3', number: '3', text: `E os feitos, em que o nosso Procurador for parte, assistente, ou oppoente, e que já forem findos, e assi os feitos e instrumentos sobre Jurisdições, Castellos e Alcaidarias Móres, e feitos de grande substancia, e de pessoas poderosas, não se darão os proprios do dito Juizo para outro algum. E sómente se darão os traslados, que as partes pedirem, sendo mandado pelos Juizes, que para isso poder tiverem.` },
        { id: 'of1-txxiii-4', number: '4', text: `E ao Scrivão de nossos feitos pertence carregar em receita sobre o Guarda Mór da Relação as peças ordenadas ao serviço della, para virem a boa arrecadação.` },
      ],
    },
    {
      id: 'titulo-xxiv',
      title: `XXIV. Dos Scrivães dante os Desembargadores do Paço e dos Aggravos, e Corregedores da Corte, e outros Desembargadores`,
      type: 'articles',
      articles: [
        { id: 'of1-txxiv-1', number: '1', text: `Os Scrivães da Corte hão de ser examinados pelos Desembargadores do Paço, tanto que houverem nossa Provisão, per que lhe fazemos mercê dos Officios, antes que hajam as Cartas delles, se sabem screver e notar, de maneira que sejam pertencentes para os ditos Officios, ou se são infamados de tal infamia, ou suspeita, que honestamente não caibam nelles. E segundo o que acharem per o exame, assi devem mandar-lhes fazer as Cartas dos Officios, ou notificar a Nós seus defeitos, para fazermos como for nossa mercê. E hão de jurar na Chancellaria.` },
        { id: 'of1-txxiv-2', number: '2', text: `E mandamos, que nenhum Scrivão se parta da Corte sem licença e mandado daquelles, perante quem screver, e do Regedor. E fazendo o contrario, será suspenso do Officio per hum anno. A qual licença lhe não poderão dar para mais, que para tres mezes em cada hum anno. E partindo-se com licença dos sobreditos, deixará todos os feitos a hum dos outros Scrivães do Juizo, em que assi screver, e lhe dará informação delles, de maneira que não sejam as partes detidas por esta razão. E o que se partir, sem deixar os feitos na maneira sobredita, pague todas as custas, perdas e danos, que pela dita maneira as partes receberem. E indo-se com licença, se andar lá mais de tres mezes, perca o Officio. E se no dito auditorio não houver mais que esse Scrivão, não lhe poderão dar licença para se ir, nem pôr outro em seu lugar.` },
        { id: 'of1-txxiv-3', number: '3', text: `Todos os Scrivães da Corte, e de cada Officio, serão diligentes e presentes em cada hum dia nas audiencias dos Desembargadores e Officiaes, perante quem screverem, em tal modo, que não errem as audiencias; e terão nellas cada hum seu livro encadernado, em que screvam os termos dellas, e o que se nellas manda, para se saber a verdade do que passou. E nos ditos livros declararão distinctamente a pessoa, que fazia a audiencia, e o dia, em que a fazia. E não screverão nas audiencias, nem tratarão cousa alguma fóra dos termos, em quanto ellas durarem. Nem mandarão a ellas seus screventes, para per elles tomarem os termos, e os Julgadores os não consentirão; mas condenarão os Scrivães, que per outrem mandarem tomar os ditos termos, ou não levarem os ditos livros, em suspensão de seus Officios até nossa mercê.` },
        { id: 'of1-txxiv-4', number: '4', text: `Os Scrivães dante os Desembargadores do Paço hão de ter hum Distribuidor, e os dos Aggravos outro, assi como tem os Scrivães dante os Corregedores da Corte, e os Scrivães dante os Ouvidores. E nenhum Scrivão tome feito, nem faça Carta, ou qualquer outro desembargo: salvo o que lhe for distribuído pelos ditos Distri- buidores, postoque diga, que são dependencias de outros feitos, de que já foi Scrivão, salvo sendo execução de sentença, que tirar do processo do feito, de que for Scrivão, ou que emanar dos ditos feitos: porque nas taes execuções poderás screver sem distribuição. E sómente se haverão por dependencias para este effeito as ditas execuções. Porém sendo sentenças, que vierem de outros Juízos, para se executarem na correição da Corte, se distribuirão entre os ditos Scrivães. E fazendo algum delles o contrário, pague o interesse ao outro Scrivão, a que houvera de ir per distribuição; e pagará outrosi as custas ás partes, e mais pague pela primeira vez quinhentos réis para a piedade, e pela segunda seja suspenso per seis mezes, e pela terceira privado do Officio.` },
        { id: 'of1-txxiv-5', number: '5', text: `E seja cada hum Scrivão avisado, que sómente screva as cousas, que a seu Officio pertencem, e não usurpe o Officio alheio per maneira alguma: salvo sendo-lhe specialmente mandado pelo Desembargador principal, a que o desembargo pertence, e do feito conhece em falta e absencia do Scrivão, cujo for o dito feito; porque de outra maneira não o deve mandar fazer, comtanto que a absencia não passe de oito dias. E bem assi, que a pessoa, a que por o absente mandar screver, seja Scrivão dante o mesmo Julgador, porque a outro Scrivão algum o não poderá commetter. E quando se em outra maneira fizer, o Regedor, ou Chanceller proveja nisso com justiça. E fazendo algum Scrivão o contrário do que dito he, pela primeira vez pague áquelle, cujo Officio usurpar, em dobro tudo aquillo, que assi houver, e pela segunda em tresdobro, e pela terceira, além do tresdobro, seja suspenso do Officio per hum anno.` },
        { id: 'of1-txxiv-6', number: '6', text: `E os Scrivães dos Aggravos não screverão, nem porão apresentação nos instrumentos de aggravo, e Cartas testemunhaveis, antes de lhes serem distribuídos, sob pena de perdimento dos Officios. E tanto que forem distribuídos, lhes porão a apresentação, e os farão conclusos: dos quaes instrumentos os ditos Scrivães não darão vista á parte, que os trouxer, salvo se a parte contraria daquelle, que aggravou, for presente, e consentir, que elle e a outra parte hajam vista. Porém, se o aggravante ajuntar ao instrumento de aggravo, antes que o apresente, alguma petição, per que declare seu aggravo, não lhe será tirada, e per a tal petição assi junta não será contada vista ao Scrivão. E vindo a outra parte contraria do que aggravou, antes que o instrumento seja finalmente despachado, e achando que o aggravante ajuntou a elle alguma petição, ser-lhe-ha dada vista do instrumento, se a quizer, para responder á dita petição e allegar de seu direito; e neste caso contar-se-ha vista ao Scrivão desta só parte, que a pedia. E se depois que o Julgador vir o dito instrumento, mandar, que o aggravante, ou parte contraria declare qualquer cousa, neste caso se contará tambem ao Scrivão vista daquella parte, ou partes, que a houverem. E será avisado o Scrivão do instrumento ou Carta testemunhavel, que depois que for publicada, a não entregue mais á parte, e a guarde, como he obrigado guardar todos os feitos; salvo se o despacho for, que pertence a outros Juízes, porque então o dará á parte, para o levar a quem pertencer.` },
        { id: 'of1-txxiv-7', number: '7', text: `E mandamos aos ditos Scrivães, que as Cartas, que os Julgadores, cujo for o desembargo, lhes mandarem fazer, as façam logo esse dia, ou até o outro pela manhã. Porém se o Julgador vir, que se não pôde fazer no dito tempo, assine para isso tempo conveniente.` },
        { id: 'of1-txxiv-8', number: '8', text: `Item, farão e tirarão as sentenças dos processos, na fórma que diremos no terceiro Livro, Titulo 66: Das sentenças definitivas, § 10.` },
        { id: 'of1-txxiv-9', number: '9', text: `E no continuar dos feitos e concertar as scripturas terão a maneira, que tem os Tabellias do Judicial, como em seu Titulo 79 se dirá.` },
        { id: 'of1-txxiv-10', number: '10', text: `E farão concertar todos os autos, que derem em Carta testemunhavel, e as Cartas, que fizerem para se tirarem inquirições per artigos; e não pondo o dito concerto, perderão os Officios, e pagarão ás partes toda a perda, dano e custas, que por elle receberem, ou se causarem. E os Julgadores não assinem taes Cartas e autos sem o dito concerto, nem os Chancereis as passem pela Chancellaria. O que tudo haverá lugar em os Scrivães dante os Corregedores das Comarcas e Ouvidores, e em todos os outros Scrivães de nossos Reinos.` },
        { id: 'of1-txxiv-11', number: '11', text: `E porque muitas vezes o Contador das custas não póde contar custas ao vencedor de sua pessoa, porque no processo não são scriptos os dias, em que a parte appareceo: mandamos a todos os Scrivães, que em os termos dos processos screvam os dias, em que pessoalmente as partes em Juizo apparecerem soltas, ou presas, ou forem ver jurar as testemunhas, postoque tenham Procuradores. E se o assi não fizerem, paguem em dobro á parte todo o dano e perda, que por isso receber.` },
        { id: 'of1-txxiv-12', number: '12', text: `E se alguma parte offerecer em Juizo alguma scriptura em ajuda de seu feito, e depois de ser em poder do Scrivão, a parte, que a deo, a tornar a pedir, não lha dará sem consentimento da outra parte, ou sem mandado do Juiz, o qual ouvirá primeiro a parte, ou seu Procurador.` },
        { id: 'of1-txxiv-13', number: '13', text: `E defendemos aos Scrivães sob pena de perdimento dos Officios, que não peçam ás partes papel, nem pergaminho, nem lho façam pagar per nenhuma via, porque da Chancellaria o hão de haver para as Cartas, que per ella passam. E quanto ao papel para os processos, devem-no elles de comprar, e não as partes. E fazendo o contrário, sejam suspensos dos Officios per hum anno. E não farão Carta alguma sem mandado daquelle, cujo for o desembargo.` },
        { id: 'of1-txxiv-14', number: '14', text: `E porão per suas mãos as pagas nas scripturas no modo e sob as penas, que o hão de fazer os Tabelliães das Notas, como em seu Titulo 80 § 16 se dirá.` },
        { id: 'of1-txxiv-15', number: '15', text: `E tendo algumas pessoas que os ajudem a screver, porão os ditos Screventes no fim das scripturas, que fizerem, o que levam dellas, não sendo porém menos da quarta parte do que se montar na scriptura. E os proprietarios, ao tempo que subscreverem, porão a paga das tres partes. O que se não entenderá nas pessoas, que forem criados dos ditos Scrivães, a que elles dêm o necessário. E fazendo o contrário, pola primeira vez tornem tudo o que levarem, á parte, e paguem outro tanto para os presos: e pola segunda hajam a mesma pena, e sejam suspensos dos Officios seis mezes: e pola terceira sejam privados dos Officios.` },
        { id: 'of1-txxiv-16', number: '16', text: `E mandamos que os ditos Scrivães ponham em todas as Cartas e sentenças e termos, que screverem, o dia, mez e anno, em que fazem as ditas Cartas, sentenças, ou termos, e assi o nome delle Scrivão, sob pena de perdimento do Officio, não screvendo cada huma das ditas cousas; e mais pagará á parte, que por isso for danificada, todo interesse, perda e dano, que por isso receber. E o dia, mez e anno porão juntamente, e não separado, como atégora se fazia.` },
        { id: 'of1-txxiv-17', number: '17', text: `E darão despacho ás partes sem detença, não lhes dando más respostas. E fazendo o contrário, e sendo provado per huma testemunha sómente, sem suspeita, sejam suspensos dos Officios per hum mez, ou mais, segundo o excesso das palavras: e seja logo feita a emenda sem outra figura de Juizo áquelles, que assi injuriarem, ou derem más respostas, em tresdobro do que lhes seria julgado, se lho outra pessoa dissesse. E não querendo a parte a dita emenda, recadar-se-ha para a arca da piedade. E havendo hi accusador, haverá o terço, e a dita arca as duas partes. O conhecimento do qual pertencerá ao Juiz do feito, ou ao Corregedor do Crime, qual a parte injuriada mais quizer.` },
        { id: 'of1-txxiv-18', number: '18', text: `Item, os Scrivães das audiencias não advogarão, nem procurarão em alguns feitos, nem poderão substabelecer, postoque procurações para isso tenham; salvo se for per nosso mandado, ou em seus feitos, ou daquelles, que viverem continuadamente com elles em suas casas, sob pena de perdimento dos Officios.` },
        { id: 'of1-txxiv-19', number: '19', text: `E os Scrivães serão avisados, que requeiram aos Juizes, que assinem as sentenças definitivas e interlocutorias, que per elles verbalmente forem dadas nas audiencias. E não as assinando no dia, em que as derem, ou até ao outro dia, pagarão às partes toda a perda, que por não starem assinadas se lhes causar. E assi façam assinar as partes as confissões e respostas, que derem a algumas perguntas, que em Juizo lhes forem feitas perante elles Scrivães, ou fóra do Juizo em algum auto, que forem fazer per mandado do Julgador, em feitos, ou causas crimes, ou civeis, o que todo farão assinar nesse dia. E não o querendo as partes assinar, notificarão ao Juiz do caso, como as partes o não querem assinar, e as causas por que. O qual Juiz perguntará duas, ou tres testemunhas per os ditos termos, scriptos pelos Scrivães, que as partes não quizerem assinar. E dizendo as testemunhas, que he verdade que as partes confessaram, ou disseram o conteúdo nos ditos termos, será dado tanto credito aos ditos termos, como se fossem pelas partes assinadas. E não o dizendo assi as testemunhas, aos taes se não dará fé alguma.` },
        { id: 'of1-txxiv-20', number: '20', text: `E sendo a dita confissão, ou resposta feita em alguma causa crime, mandamos ao Scrivão, que requeira a parte nesse dia, que assine, e não querendo assinar, o diga ao Julgador; o que todo assentará per termo, declarando a causa, por que a parte não quiz assinar, e o Julgador assinará o dito termo da confissão ou resposta, e o mesmo Scrivão, que a screveo, e outro Scrivão, que presente stiver ás ditas perguntas, ou confissão. E não havendo ahi outro Scrivão, será assinado per duas testemunhas, que presentes starão ás perguntas e confissões. E feita a dita diligencia, será dada tanta fé ao dito termo, como se pela parte fosse assinado. E os termos das confissões, ou respostas, assi em causa civel, como crime, que na sobredita maneira não forem feitos, havemos por nenhuns, e de nenhum effeito.` },
        { id: 'of1-txxiv-21', number: '21', text: `E quanto aos outros termos prejudiciaes, assi como renunciações, fianças, cauções, louvamentos, pactos, convenças, que em Juizo se fizerem, procurações apud acta. O Scrivão requererá as partes, que as fizerem, dentro no mesmo dia, que as assinem. E não as querendo assinar, serão de nenhum effeito; e o Scrivão, que screver os ditos termos, e os não fizer assinar no mesmo dia, ou não declarar ao Julgador até o dia seguinte, como a parte não quiz, nem foi assinar, sendo-lhe per elle requerido, e sendo o feito civel, pagará à parte toda a perda e dano, que por sua negligencia, ou culpa se causar. E se o feito for crime, alem da pena sobredita, será suspenso do Officio um anno. E a todos os outros termos, que não forem dos sobreditos, havemos por bem que lhes seja dada tanta fé, como se fossem assinados per as partes, postoque per ellas assinados não sejam.` },
        { id: 'of1-txxiv-22', number: '22', text: `E porque muitas vezes por negligencia dos Julgadores, ou de seus Scrivães se perdem alguns feitos, de que se segue muito dano às partes, e perda de sua justiça; mandamos que o Scrivão, que tiver o feito, tanto que for concluso, o leve per si ao Desembargador, a que primeiro for distribuído, e não lho mande per moço, nem per outra pessoa alguma; e quando lho entregar, mostre-lhe o feito, se ha nelle alguma interlinha, borradura, ou outro vicio algum, e de tudo fará um termo no feito, em que declare o lugar, mez e anno, em que lho entrega, que será assi- nado pelo dito Desembargador, sob pena de o Scrivão ser suspenso per tempo de dous mezes, cada vez que assi o não cumprir. E cada um dos Desembargadores, que dos ditos feitos conhecer, quando vir que o Scrivão não cumpre o acima dito, o poderá suspender pelo dito tempo, e o mesmo fará o Chanceller da Casa, quando vier à sua notícia, se já não stiver feito pelo Desembargador; e não querendo o Desembargador assinar no feito, não lho dê, e vá ao outro dia à Relação, aonde stiver o dito Desembargador, e o diga ao Regedor, para o reprehender, e lhe fazer pagar as custas às partes, as quaes lhe logo serão pagas.` },
        { id: 'of1-txxiv-23', number: '23', text: `E depois que o feito for visto pelo primeiro Desembargador, o entregará ao segundo, que assinará no dito feito, como o recebeo, assi como fez o primeiro. E assi dali em diante todos os que o dito feito receberem.` },
        { id: 'of1-txxiv-24', number: '24', text: `E perdendo-se o feito em poder de algum dos Desembargadores, tendo-o recebido, e assinado no feito, como dito he, pagará à parte, ou partes as despessas, que no tal feito tinha feitas de sua pessoa e processo, e assi da dilação e perda de sua justiça: e haverá mais qualquer outra pena crime, ou no Officio, se parecer que pelo tal caso a mereceo; o que tudo determinará o Regedor com alguns Desembargadores, que lhe bem parecer.` },
        { id: 'of1-txxiv-25', number: '25', text: `E o Scrivão, que o feito entregar sem o termo sobredito, perdendo-se o feito, não lhe será recebida prova alguma a dizer que o tem entregue, e haverá as penas, que acima stão ditas no paragrafo 22: E porque. E em nenhum caso lhe poderá ser dada menos pena, que de suspensão do Officio, até o feito ser reformado e achado, o que tudo determinará o Regedor com os Desembargadores, que lhe bem parecer. E se o Scrivão per qualquer outro modo perder o feito, e não der delle a conta, que deve, alem de pagar as perdas, danos, e custas às partes, será privado, ou suspenso de seu Officio de Scrivão pelos Juizes do feito, segundo a qualidade do caso e culpa, que tiver.

Das sentenças sobre a pertinência de autos pendentes, he permitido o agravo de petição ou instrumentos, de autos julgados à final, appellação.` },
        { id: 'of1-txxiv-26', number: '26', text: `E se for duvida entre o Scrivão e o Procurador sobre o perdimento do feito, não será crido o Scrivão: salvo se provar, como lho entregou.` },
        { id: 'of1-txxiv-27', number: '27', text: `Outrosi mandamos a todos os Scrivães, que por nossa parte, ou pelos Rendeiros e feitor da Chancellaria forem requeridos, que dêm e mostrem per seus assinados as condenações das sentenças, que elles as dêm logo, sob pena de privação de seus Officios.` },
        { id: 'of1-txxiv-28', number: '28', text: `E serão obrigados os Scrivães fazer as diligencias e citações, que para nossos feitos forem necessarias fazer-se, e execucões das Cartas e sentenças, que aos ditos feitos pertençam com diligencia: e sem por isso levarem cousa alguma, sendo-lhes mandado per qualquer Julgador, que do caso conheça, ou requerido per algum dos Procuradores, ou Sollicitadores de nossa Coroa, ou Fazenda. E não o fazendo assi, pola primeira vez pagarão dez cruzados para as despesas da Fazenda, ou Relação, donde a Carta sair. E sendo de outros Julgadores, será a dita pena para os Captivos. E por a segunda vez serão privados dos Officios, e não os poderão mais haver sem nosso special mandado. E os Corregedores, Contadores e Juizes farão executar as ditas penas. E não as executando, serão executadas em cada hum dos ditos Julgadores.` },
        { id: 'of1-txxiv-29', number: '29', text: `E todos os Scrivães e Porteiros, a que o Sollicitador dos feitos de nossa Coroa, ou Fazenda requerer de nossa parte, que vão chamar Fidalgos e pessoas de outra qualquer qualidade, para darem seus testemunhos nos feitos de nossa Coroa, ou Fazenda; e farão com muita brevidade, e diligencia; e os requererão que vão dar seus testemunhos à Fazenda, ou Relação, e dello darão razão aos Julgadores, que os houverem de tirar, para procederem contra as pessoas, que não forem testemunhar. E bem assi citarão as partes, que lhes for mandado, para ver jurar testemunhas, ou para fallar a algum feito, sem por isso levarem dinheiro algum. E as Cartas, que houvessem de fazer, as farão com brevidade, e feitas e assinadas pelos Juizes, as entregarão ao Sollicitador, para as passar pela Chancellaria, e as dar aos nossos Procuradores, para as mandarem.` },
        { id: 'of1-txxiv-30', number: '30', text: `E os Scrivães, a que forem pedidos per mandado de alguns Desembargadores traslados de algumas sentenças, contractos, scripturas, feitos e inquirições, que pertençam a feitos de nossa Coroa, ou Fazenda, em que o nosso Procurador he parte, os dêm fielmente concertados sem tardança alguma, sem por isso pedirem dinheiro algum. E o que assi o não cumprir, pagará por cada vez vinte cruzados para os Captivos. E o que se contém neste paragrapho, e nos dous proximos precedentes, se cumprirá, assi na Corte, como em qualquer lugar de nossos Reinos e Senhorios, onde se as taes diligencias houverem de fazer.` },
        { id: 'of1-txxiv-31', number: '31', text: `E assi darão quaesquer feitos, que lhe forem pedidos pelo nosso Procurador da Coroa, ou Fazenda, per seu assinado, assi os findos, como os que o não forem ainda: e lhos levarão para os verem, e tomarem informação do que tiverem necessidade, ou os entregarão ao Sollicitador, para que lhos leve, e cobrarão dos ditos Procuradores conhecimento, per que se obriguem a lhos tornar, como forem vistos. E isto cumprirão com toda a diligencia, sem por isso levarem cousa alguma, sob pena de vinte cruzados, ametade para os Captivos, e a outra para o accusador. Porém os feitos, que os ditos Procuradores pedirem, que ainda penderem, não poderão tel-os em suas casas mais que hum dia.` },
        { id: 'of1-txxiv-32', number: '32', text: `Outrosi todos os Scrivães dante os Corregedores e Ouvidores, ou quaesquer outros Desembargadores, que screverem em feitos crimes, screvam nelles com muita diligencia, e façam logo todas as Cartas, que saírem para se fazerem diligencias, ou execuções, e as dêm a assinar aos Desembargadores, per quem houverem de ser assinadas. E tanto que assinadas forem, as entreguem ao Promotor da Justiça, para as logo fazer sellar, e enviar pelos Caminheiros aos lugares, para onde vão dirigidas. O que assi mandamos que se faça nos ditos feitos crimes, para mais brevemente serem desembargados, ora delles na Corte haja partes, ou requerentes, ora não.` },
        { id: 'of1-txxiv-33', number: '33', text: `E aos Scrivães dante os Corregedores do Crime da Corte pertence screver as devassas sobre mortes e arrancamentos de armas, ou ferimentos, que se na Corte fizerem. E dos casos, de que devassarem, poderão receber querellas com os ditos Corregedores, e farão todos os livramentos, que se sobre as ditas devassas derem, emquanto se per ellas não receber libello. Porque como o libello for recebido (ora ahi haja parte, ora se dê libello por parte da Justiça), logo se deve distribuir entre elles. E hão de screver todas as penas das armas e de sangue, que na Corte se tirarem, e por nossa parte, ou de nosso Rendeiro forem demandadas; e tirarão sobre ello as inquirições judiciaes, das quaes não levarão dinheiro, por bem do mantimento, que por isto hão.` },
        { id: 'of1-txxiv-34', number: '34', text: `E quando alguns presos forem remettidos às Ordens, e seus feitos se tratarem e começarem na Corte, ou o proprio original vier a ella, assi como se faz onde stá a Casa da Supplicação, ou a do Porto, ou per nosso special mandado o proprio feito for trazido à Corte, os ditos feitos se trasladem, e os traslados concertados com os proprios sejam enviados, cerrados e sellados, aos Juizes Ecclesiasticos. E quando os feitos vierem à Corte per appellação com o traslado dos autos processados na terra, o proprio traslado, que da terra vier, seja enviado aos Juizes Ecclesiasticos, a que os presos forem remettidos, quer na mór alçada e causa da appellação crescessem novos autos, quer não. Porém ao Julgador da mór alçada fique (se vir que os novos autos, que na causa da appellação crescerem, são necessarios por bem da Justiça) os mandar trasladar primeiro à custa da parte remettida, para serem levados à terra, e juntos ao proprio original da appellação, e com elles e com o proprio original da terra ter a Justiça secular o teor de todo, assi como vai nos autos.` },
        { id: 'of1-txxiv-35', number: '35', text: `E todas as inquirições devassas de mortes, que os Juizes hão de mandar à Corte, serão entregues ao Distribuidor; o qual, sem as abrir, as distribuirá a cada hum dos ditos Scrivães, e lhas entregará na audiencia, ou em sua casa, ou lhas enviará pelo mesmo Caminheiro, que as trouxer; e os conhecimentos, que se derem aos que as ditas devassas entregarem, serão feitos pelo dito Scrivão, e assinados per elle e pelo Distribuidor, do qual conhecimento levarão sómente quatorze réis, cada hum delles sete réis; os quaes quatorze réis recadará o Scrivão do que primeiro se vier livrar, e dará ametade ao Distribuidor. E do dia, que o Scrivão qualquer inquirição devassa houver, a oito dias, será obrigado levai-a per sua propria pessoa, e a não mandará per moço, nem per outrem ao Promotor da Justiça, para della tirar a rol todos os culpados, e requerer aos Corregedores, que os mandem prender. E tudo isto cumprirão sob pena de perdimento dos Officios. E per esta maneira as levarão ao Julgador, quando a elle houverem de ir. E se as Justiças em mandar pelo Sollicitador da Justiça, o poderão fazer; o qual lhas levará logo, e lembrará, que as despache. Porém se as taes devassas vierem à Corte per Carta, para alguns homiziados haverem perdão, devem vir aos Desembargadores do Paço, e os Scrivães dante elles screvam os despachos, que nellas derem.` },
        { id: 'of1-txxiv-36', number: '36', text: `Item, cada hum dos ditos Scrivães fará hum livro, em que screva as sentenças, que cada hum dos ditos Corregedores der, que sejam de quinhentos e quarenta réis para cima, pondo o dia, mez e anno, e lugar em que he dada, e onde moram as partes, e a causa, ou quantidade, que he julgada, fazendo tal declaração dos nomes das partes, que em certo se possa saber quem são, e onde moram. O qual livro levarão emfim de cada hum mez à Chancellaria, para per elle e pelo Scrivão da Chancellaria se saber, se são tiradas todas as ditas sentenças, e a dizima e a Chancellaria para Nós recadadas. E as que não forem tiradas, o Scrivão da Chancellaria faça assentar as verbas no livro, e faça as Cartas de execução, per que as dizimas das taes condenações se recadem.` },
        { id: 'of1-txxiv-37', number: '37', text: `Item, todas as inquirições, capítulos e cousas de malfeitorias de qualidade, que alguma parte possa pretender satisfação, ou interesse de alguma perda, ou dano (postoque a não demande), que do Reino vem à Corte, ora venham per nosso mandado, ora sem elle, hão de vir aos ditos Scrivães, e per elles se distribuirão igualmente. E aquelle, a que for distribuido, screverá nos livramentos, que os Corregedores da Corte, ou outro qualquer Julgador, a que o Nós commettermos, sobre elles derem, quer o dito livramento haja de correr com a Justiça, quer com a parte, ora o feito venha já processado da terra, ou por processar, ou per nosso mandado, ou sem elle.` },
        { id: 'of1-txxiv-38', number: '38', text: `E ao Scrivão, que screver ante o Corregedor, que em nossa Corte andar, pertence screver todas as malfeitorias, que se fizerem, e danificamentos de camas e casas de aposentadoria de nossa Corte, tirando aquella roupa, de parecer que se gasta em seu serviço. E o dito Corregedor ha de ordenar, que sejam pagas, segundo stá declarado em seu Regimento. E o dito Scrivão trará em hum livro todos os Regatães e mulheres solteiras, e aos Regatães ha de fazer seus privilegios, como sempre se usou.` },
        { id: 'of1-txxiv-39', number: '39', text: `E os Scrivães dante os Ouvidores da Casa da Supplicação e da do Porto cada mez lhes darão conta se são feitas as diligencias, que per bem de Justiça são mandadas fazer, e a causa, por que se não fizeram. E o que assi o não cumprir, incorrerá em pena de suspensão de seu Officio, na qual cada hum dos Ouvidores condenará o Scrivão dante elle, sem appellação, nem aggravo, não passando a tal suspensão de seis mezes.` },
        { id: 'of1-txxiv-40', number: '40', text: `E para que se não dê occasião aos Scrivães dante os Ouvidores do Crime de fazerem as partes tomar os Procuradores, que elles querem, e não os que querem as mesmas partes, e de razoar os feitos por causa das vistas, que pagam: mandamos que nenhum Scrivão dante os Ouvidores tome procuração das partes em sua causa, salvo em audiencia, nem de outra maneira de vista para razoar os ditos feitos, nem obriga as partes a tomar Procuradores contra suas vontades.` },
        { id: 'of1-txxiv-41', number: '41', text: `E os Scrivães não deterão em maneira alguma os feitos, por dizerem que as partes lhes não pagam, mas farão tudo o que nelles devem fazer, e requererão aos Julgadores, que lhes façam pagar o que hão de haver das partes, e os Julgadores lho mandem logo pagar. E os que pagar não quizerem, sejam logo penhorados, ou presos, se taes pessoas forem, que o devam ser, e paguem da cadéa.` },
        { id: 'of1-txxiv-42', number: '42', text: `E porque ás vezes as partes se vão da Corte, tanto que seus feitos são findos, sem pagarem aos Scrivães, mandamos que a parte vencedora, ora seja autor, ou réo, assi em feito civel, como crime, se tirar sentença, pague na Corte aos Scrivães della todo o que no feito lhe for contado da sua scriptura, assi da parte do vencedor, como do vencido; e pôr-se-ha na sentença huma clausula, que diga: E bem assi fareis execução em tantos bens do dito condenado, per que o dito vencedor haja mais tanto, que pagou por elle ao Scrivão deste feito em nossa Corte, que ao dito vencido pertencia pagar, e não pagou. E isto não haverá lugar, quando a sentença for de absolvição, e sem custas, salvo se o vencedor e o vencido forem moradores em hum lugar; porque se forem moradores em differentes lugares, não será o que houve a sentença de absolvição, e sem custas, obrigado pagar ao Scrivão o que lhe a outra parte dever, que pois elle não ha de fazer execução pela sentença, para haver para si cousa alguma, não deve ser constrangido a ir fôra de sua casa recadar o que ao Scrivão he devido. Mas em tal caso o Scrivão mande fazer execução nos bens daquelle, que lhe não pagou, como se faz pelas dizimas das sentenças, que para Nós se recadam.` },
        { id: 'of1-txxiv-43', number: '43', text: `E quanto ao pagamento dos feitos dos presos pobres, que na Casa da Supplicação per nova aução se tratarem, ou per appellação, ou aggravo a ella vierem, se depois de finalmente serem desembargados, os ditos presos, ou outrem por elles não tirarem suas sentenças até dous mezes, contados do dia da publicação, por dizerem, que são tão pobres, que não tem per onde pagar o salario aos Scrivães: mandamos ao Chanceller da Casa, que fazendo elles certo de sua pobreza, mande contar os feitos; e tudo o que se achar per conta, que os ditos presos devem aos Scrivães de seu salario, e ao Procurador dos pobres (se por elles procurou), lhes mande pagar ametade de seus salarios do dinheiro da Chancellaria da dita Casa. E per seus mandados fará o Recebedor da Chancellaria os pagamentos perante o Scrivão della, para lhe serem levados em conta, e para a outra ametade lhes ficará seu direito resguardado para a haverem dos ditos pobres, depois que tiverem per onde pagar.` },
        { id: 'of1-txxiv-44', number: '41', text: `E todo o que dito he ácerca do pagamento dos feitos dos presos pobres, não haverá lugar nos presos, que forem remettidos ás Ordens, ou tornados á immunidade da Igreja, ou a algum Couto de nossos Reinos, aonde stavam acoutados.` },
        { id: 'of1-txxiv-45', number: '45', text: `E tanto que os feitos crimes dos presos forem finalmente desembargados, os Scrivães os levarão no mesmo dia, que se publicarem, aos Contadores; os quaes os contarão logo até per todo dia seguinte, a mais tardar, e não os reterão mais em seu poder por seu salario, nem do Scrivão, nem Procurador; mas logo os entregarão ao Corredor das folhas, que disso tiver cuidado, ou ao Sollicitador da Justiça, qual os primeiro pedir. E do que acharem que os taes presos lhes devem de seus salarios, poderão haver Alvará de embargo dos Juizes dos ditos feitos, e não serão soltos até pagarem. E tendo os taes presos alguma fazenda, poderão os ditos Officiaes requerer per ella seus pagamentos, que lhes os ditos Juizes mandarão fazer, não sendo porém seus feitos embargados, nem retardados. E por cada vez que os Contadores, ou Scrivães o contrario fizerem, pagarão mil réis para as despesas da Relação, e perderão o que dos taes feitos houverem de levar, ou tiverem levado.

Esta disposição comprehende tambem Juízes e advogados.

E quanto aos presos das Ordens confronte-se esta com as Ords. do liv. 2 t. 1 § 27 e t. 3 § final, liv. 3 t. 67 § 5, e liv. 5 t. 124 § 13 e t. 132 § 2.` },
        { id: 'of1-txxiv-46', number: '46', text: `E serão avisados os Scrivães, que tanto que o feito for findo, dentro de hum mez o mandem ao Contador das custas, para 'o contar, postoque per nenhuma das partes lhes seja requerido, em modo que se saiba se levaram mais de alguma das partes, do que per Direito lhes era devido. E não o mandando no dito tempo, incorrerão em pena de perdimento dos Officios. O que haverá lugar nos Scrivães das audiencias, Tabelliães, Scrivães dos Concelhos, Scrivães de quaesquer nossos Officios, de qualquer qualidade que sejam.` },
        { id: 'of1-txxiv-47', number: '47', text: `E nenhum dos ditos Scrivães leve mais das scripturas do que lhe directamente montar, e per nossas Ordenações lhe he taxado, nem dos processos que screver. E fazendo o contrario, haverá as penas contendas no Livro quinto, Titulo 72: Das penas que haverão os Officiaes, que levam mais, etc. E bem assi, não tomem pão, vinho, nem outras cousas, de qualquer qualidade que sejam, de pessoa alguma, sob pena de perdimento dos Officios, e de haverem as mais penas declaradas no Livro quinto, no Titulo 71: Dos Officiaes del Rei que recebem servicos, ou peitas. E quando receberem alguma cousa adiantado, antes de lhes ser contado, das partes, que perante elles feitos trouxerem, não se poderão escusar, por dizerem, que lho descontaram, ou descontarão de seu salario. O que outrosi haverá lugar nos Tabelliães e Scrivães, de qualquer qualidade que sejam.` },
        { id: 'of1-txxiv-48', number: '48', text: `E todo o que neste titulo he dito, cumprirão e guardarão os Scrivães e Tabelliães dante quaesquer outros Julgadores naquillo, em que se a elles poder applicar.` },
      ],
    },
    {
      id: 'titulo-xxv',
      title: `XXV. Do Guarda Mór da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-txxv-preambulo', number: 'Preâmbulo', text: `O Guarda Mór da Relação em cada hum dia pela manhã cedo concertará as mesas, cadeiras e pannos, e todo o mais necessário para o despacho, como he costume: de modo que quando os Desembargadores chegarem, se possam logo assentar a despachar, e não haja occasião de se de terem por falta do sobredito. E terá cuidado de guardar a tapeçaria e o mais movel do serviço da Relação, de maneira que de tudo de boa conta, quando lhe for mandado. O que todo lhe será entregue per mandado do Regedor, e carregado em receita pelo Scrivão dos nossos feitos.` },
        { id: 'of1-txxv-1', number: '1', text: `E guardará a porta da Relação em cada hum dia, sem d'ella se apartar, em quanto a Relação durar, salvo per mandado do Regedor, e não deixará entrar pessoa alguma dentro, senão per seu mandado. E vindo algum Fidalgo, ou outra pessoa, lhe dirá que por então não póde entrar, e que mande per scripto o que lhe cumprir a quem quizer. E elle terá cuidado de levar os ditos scriptos e trazer as respostas, sem por isso levar cousa alguma. E não se chegará ás mesas do despacho, senão quando for chamado per campainha, e tanto que lhe for dito o para que foi chamado, se sairá logo: e fazendo o contrario, o Regedor o castigue como lhe parecer.` },
      ],
    },
    {
      id: 'titulo-xxvi',
      title: `XXVI. Do Solicitador da Justiça da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-txxvi-preambulo', number: 'Preâmbulo', text: `O Solicitador da Justiça da Casa da Supplicação será diligente em maneira, que por sua mingoa e negligencia não se dilatem os feitos da Justiça e dos presos. Para o que terá hum livro encadernado de tanto papel, quanto for necessário para nelle se assentarem os feitos dos casos crimes de cada anno, que se houverem de tratar perante os Corregedores da Corte, no qual fará titulos apartados de cada hum dos Scrivães. E no titulo de cada Scrivão fará declaração de cada preso, de seu nome, appelido, e terra, d'onde he natural, e caso, por que he accusado, e quem he Juiz do feito e Procurador.` },
        { id: 'of1-txxvi-1', number: '1', text: `E mais adiante assentará per Itens os que se livrarem per Cartas de seguro, ou Alvarás de fiança, com as mesmas declarações, declarando outrosi se as Cartas são com defesas, ou negativas, e os Alvarás de quanto tempo, e de que casos são. E da mesma maneira assentará todos os que forem emprazados por casos crimes.` },
        { id: 'of1-txxvi-2', number: '2', text: `E em outro titulo assentará as devassas dos casos acontecidos na Corte, e as que do Reino a ella vierem, para o que irá cada mez huma vez à casa de cada hum dos Scrivães e do Distribuidor; os quaes lhe mostrarão as devassas, e perante elles fará os ditos assentos, pelos quaes requererá ao Promotor da Justiça, que as veja, para cumprir o que se contém em seu Regimento. E os Scrivães e Distribuidor não lhe negarão devassa alguma, sob pena de privação de seus Ofícios.` },
        { id: 'of1-txxvi-3', number: '3', text: `E irá com o Promotor da Justiça o primeiro dia de cada mez à cadeia da Corte, e tomará em rol todos os presos, que nella houver, para o Regedor lhes mandar dar livramento, com as declarações do princípio deste Titulo.` },
        { id: 'of1-txxvi-4', number: '4', text: `E será sempre presente com o seu livro nas audiencias dos Corregedores do Crime da Corte, e lembrará todos os ditos feitos, lendo o Item de cada hum, comecando pelo rol do Scrivão mais antigo. E requererá ao Julgador que mande ao dito Scrivão, que declare os termos, em que o feito stá, ouvindo o preso e o accusador, ou o Promotor da Justiça; e não sendo presente o Promotor, fará o Sollicitador pôr o feito em termos. E depois da audiencia acabada, irá saber do Scrivão, se escreveu o que na audiencia passou, specialmente nos feitos, em que a Justiça he parte. E requererá que se façam todas as diligencias, que cumprirem ao feito, e que pelo dito Julgador forem mandadas fazer. E na audiencia seguinte accusará a negligencia dos Ofíciaes, que eram obrigados a fazei-as, para o Julgador prover, como for Justiça. E quando os feitos stiverem conclusos, lembrará o despacho delles aos Julgadores, e se cumprir, ao Regedor.` },
        { id: 'of1-txxvi-5', number: '5', text: `E quando os feitos dos presos stiverem em dilação, saberá quaes testemunhas se hão de perguntar por parte da Justiça, e fal-as-ha com diligencia citar, para virem dar seus testemunhos. E se não vierem, requererá os Julgadores que os constranjam. E o mesmo fará ás testemunhas, que os presos pobres nomearem. Porém, se forem taes pessoas, que devam ser perguntadas em suas casas, faça com o Scrivão e Enqueredor, que as vão lá perguntar: e se forem nisso negligentes, diga-o aos Julgadores, a que pertencer.` },
        { id: 'of1-txxvi-6', number: '6', text: `E por quanto os que se livram per Alvarás de fiança, são obrigados apparecer em todas as audiencias, e fallarem a seus feitos; mandamos, que não apparecendo elles, ou não se fallando por sua parte, o Sollicitador os faça pregoar, e falle nos seus feitos pelos assentos do livro. E havendo delles culpas obrigatorias, passados os termos, em que houverem de apparecer, o Julgador os mandará prender, por não seguirem os termos dos Alvarás. E a mesma ordem se terá com os seguros.` },
        { id: 'of1-txxvi-7', number: '7', text: `E em titulo apartado fará assento de todas as Cartas de inquirições e diligencias, que se houverem de fazer per bem da Justiça, declarando o nome do Julgador, que assinou cada huma, e do Scrivão que a fez, e do Caminheiro, a que se entregou, e em que dia lhe foi entregue, e sobre que caso, e para quem foi dirigida, no qual assento assinará o dito Caminheiro perante o Promotor. E terá lembrança, quando o Caminheiro tornar, de lhe pedir a certidão da diligencia, se for feita, ou da pessoa, a que entregou a Carta, a qual certidão juntará ao feito. E havendo dilação no fazer da dita diligencia, requererá ao dito Julgador, que a passou, que mande proceder contra a pessoa, que a houvera de fazer: e sendo necessario, o fará saber ao Regedor.` },
        { id: 'of1-txxvi-8', number: '8', text: `E terá outro livro, em que pela mesma ordem assentará as appellações dos feitos crimes, que vierem aos Ouvidores; pelo qual livro fallará nos feitos, em que não houver accusador, que stiverem conclusos, e nos que os Procuradores eram obrigados a dar. E os fará pôr em termos nas audiencias dos ditos Ouvidores, e nas Cartas de inquirições e diligencias das ditas appellações guardará o que fica dito nas diligencias dos feitos da correição.` },
        { id: 'of1-txxvi-9', number: '9', text: `E mandamos, que quando as ditas devassas, ou inquirições, antes de abertas e publicadas, houverem de ir aos Julgadores, ou ao Promotor, os mesmos Scrivães as levem per si, e as não mandem per moços, nem per outra pessoa alguma. E o Scrivão, a que forem distribuídas, dará dellas conhecimento ao Caminheiro, assinado per elle e pelo Distribuídor, sem por isso levar cousa alguma ao dito Caminheiro, ou á pessoa, que lhas entregar.` },
        { id: 'of1-txxvi-10', number: '10', text: `E o Sollicitador fará lembrança na audiencia ao Julgador, que a fizer, que pergunte ao Distribuídor quantas devassas lhe trouxeram, e se são distribuídas, e não o sendo, as faça logo distribuír. E pelo livro da distribuição o Sollicitador as assentará no seu livro, para dahi em diante fazer as diligencias acima ditas. E irá a casa dos Scrivães lembrar-lhes, que as mandem aos Julgadores, ou ao Promotor, e se os Scrivães as quizerem mandar per elle, as levará. E nas audiencias fallará nellas, para que o Promotor com brevidade venha com libellos, e faça o mais, que a seu Officio pertença. E o Sollicitador, que assim não cumprir, pola primeira vez será suspenso per seis mezes: e pola segunda per hum anno: e pola terceira será privado do Officio, e haverá as mais penas, em que segundo nossas Ordenações polos ditos casos incorrer.` },
      ],
    },
    {
      id: 'titulo-xxvii',
      title: `XXVII. Dos Distribuídores da Corte e Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-txxvii-preambulo', number: 'Preâmbulo', text: `Mandamos, que onde houver dous Scrivães, haja hum Distribuídor, que entre elles distribua todos os feitos, Cartas, desembargos, ou autos, que lhes pertencerem fazer, em modo que todos sejam igualados nas scripturas.` },
        { id: 'of1-txxvii-1', number: '1', text: `E na mesa do despacho dos Desembargadores do Paço haverá hum Distribuídor para distribuir entre elles as petições, que per bem de seu Regimento lhe hão de ser distribuídas: E para distribuir entre os Scrivães dante os ditos Desembargadores do Paço as Cartas, que houverem de fazer.` },
        { id: 'of1-txxvii-2', number: '2', text: `E na Casa da Supplicação haverá hum Distribuídor entre os Desembargadores dos Aggravos, e os Juizes dos nossos feitos e Ouvidores, Scrivães e Contadores dos ditos Juizos.` },
        { id: 'of1-txxvii-3', number: '3', text: `Querendo dar fórma, que aos ditos Desembargadores dos Aggravos sejam distribuídos a hum tantos feitos, como a outro, mandamos, que haja hum só livro de distribuição, para se distribuírem os feitos e instrumentos de aggravo e appellações entre os ditos Desembargadores igualmente. No qual livro o Distribuídor ao tempo que distribuir entre os Scrivães, distribuirá logo a qual Desembargador vai o feito, e lho carregará na distribuição, e o porá logo por sua letra no feito. E as feitos, que da Casa do Porto vierem á Casa da Supplicação, e nella tem certos Scrivães, tanto que vierem ao aggravo, antes das partes razoarem, os distribuírá entre os Desembargadores, e lhes porá a que Desembargador vão. E fará no dito livro hum titulo dos feitos grandes, e outro dos pequenos, e assi dos instrumentos de aggravo, Cartas testemunhaveis e dias de apparecer, em modo que sejam distribuídos a cada Desembargador tantos grandes e pequenos, e tantos instrumentos de aggravo, como a outro. E assi os distribuírá por grandes ou pequenos aos Scrivães, como aos Desembargadores. E todos os instrumentos de aggravo e Cartas testemunhaveis serão distribuídos; e os Scrivães, a que distribuídos forem, lhes porá a apresentação, e os farão conclusos. E em quanto distribuídos não forem, não lhes porão apresentação, sob pena de perdimento dos Offcios.` },
        { id: 'of1-txxvii-4', number: '4', text: `E o dito Distribuídor, distribuírá outrosi os feitos, appellações, instrumentos, Cartas testemunhaveis e dias de apparecer, que os Juizes dos nossos feitos e da Fazenda houverem de despachar igualmente, assi entre os Juizes, como entre os Scrivães, que screverem per distribuição.` },
        { id: 'of1-txxvii-5', number: '5', text: `E assi mesmo distribuírá igualmente as appellações dos feitos crimes entre os Ouvidores e Scrivães dante elles, fazendo dellas tantas partes, quantos são os Ouvidores do Crime, sem declarar a qual delles ha de ir, por quanto esta declaração pertence ao Regedor da Casa da Sup- plicação, como em seu Titulo 1 § 35 se contém.` },
        { id: 'of1-txxvii-6', number: '6', text: `E bem assi haverá hum Distribuidor, que distribua os feitos, scripturas e Cartas, que houverem de screver os Scrivães dante os Corregedores da Corte, a cujas audiencias será obrigado ir e levar o livro da distribuição; e lhe serão entregues as devassas, que do Regno vem aos Scrivães do Crime, e as distribuirá entre elles cerradas como vierem, sem as abrir, de que fará assento no livro da distribuição, pelo titulo, que vem nas costas dellas, em que se declara o caso. E pelo mesmo Caminheiro, ou pessoa, que lhas entregar, as enviará ao Scrivão, a que forem distribuidas, o qual dará conhecimento dellas ao Caminheiro, assinado per elle e pelo Distribuidor. E levará a audiencia o livro da distribuição, e nella distribuirá as devassas, que ainda não tiver distribuidas.` },
        { id: 'of1-txxvii-7', number: '7', text: `E os autos das prisões não se distribuirão, mas serão entregues aos Scrivães dos feitos. Nem se distribuirão as execuções das sentenças, mas screverão nellas os Scrivães, que foram dos feitos quando as execuções se tratarem perante os Juizes, que deram as sentenças. E as sentenças, que vierem de outros Juizes, para se executarem na correiçam da Corte, se distribuirão entre os Scrivães della, e o mesmo será em outros quaesquer Juizos. E os feitos principiados nas ferias se distribuirão entre os Scrivães, que ao tal tempo fôrem presentes nas audiencias, que os Corregedores fizerem.` },
        { id: 'of1-txxvii-8', number: '8', text: `E as distribuições se farão em cada hum dia no lugar e horas, que sempre se costumaram fazer. E dar-se-ha distribuição aos Scrivães presentes, e não aos absentes: porém sendo algum absente per nosso mandado, ou do Regedor, ou por outro caso, que pertença a nosso serviço, ou por alguma evidente necessidade (o que lhe será crido per seu juramento, que o Chanceller lhe dará), não lhe será negada distribuição, e ser-lhe-ha feita entrega, depois que vier, se a absencia for per poucos dias, de maneira que não fique outrem servindo seu Officio. E sendo absente sem a dita licença, ficará por entregar.` },
        { id: 'of1-txxvii-9', number: '9', text: `E depois que um feito for distribuido, postoque as partes se concertem em principio da demanda não se riscará do livro da distribuição, nem se dará ao Scrivão outro feito em lugar daquelle.` },
        { id: 'of1-txxvii-10', number: '10', text: `E os Distribuidores levarão de cada feito, ou auto, ou outra cousa, que distribuirem, seis réis. E não levarão busca, senão quando passar de cinco annos, que o feito for distribuido.` },
      ],
    },
    {
      id: 'titulo-xxviii',
      title: `XXVIII. Do Thesoureiro dos depositos da Corte e Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-txxviii-preambulo', number: 'Preâmbulo', text: `Mandamos, que todo o dinheiro, prata, ouro, joias e quaesquer penhores, de Os móveis corruptiveis depositados pagão 2 % de deposito, não sendo ouro, prata, pedras preciosas e dinheiro liquido, que pagão sómente 1 % deduzido do capital no tempo da entrada. Do deposito voluntario não se exige salario algum.

qualquer sorte e qualidade que sejam, que per via de Justiça, ou per qualquer outro modo se mandarem depositar, ou sequestrar na Corte e Casa da Supplicação, se depositem em mão do Thesoureiro dos depositos de nossa Corte e Casa da Supplicação. E bem assi todas as quantias de dinheiro e penhores, que quaesquer pessoas quizerem entregar e depositar em Juizo para guarda e conservação de seu direito. E tudo o que assi lhe for entregue, lhe será carregado em receita pelo Scrivão de seu carrego em hum livro, que para isso terá, o qual será numerado, e as folhas assinadas no principio de cada lauda pelo Julgador, ou pessoa, per Nós para isso ordenada. O qual Scrivão fará assento apartado no dito livro de cada entrega, que se fizer ao dito Thesoureiro, assi per mandado da Justiça, como a requerimento das partes, ou per outro qualquer modo, com declaração do dia, mez e anno, e da quantia do dinheiro, peso, sorte e valia de cada huma das peças de ouro, ou de prata, joias e outros penhores, e das pessoas, cujos são, e porque causa e razão se depositam, e per cujo mandado, com todas as demais declarações necessárias, para não poder haver engano, ou enleio. E em cada assento assinará o Thesoureiro e o Scrivão, e de todo o que lhe assi for entregue e carregado em receita, dará as partes conhecimentos em fórma.` },
        { id: 'of1-txxviii-1', number: '1', text: `E serão obrigados o Thesoureiro e Scrivão ir per todos os auditorios da Corte e Casa da Supplicação, quando nella se fizerem as audiências, para saber se ha alguns depositos para receber; e havendo-os, lhes serão logo entregues e carregados em receita pelo modo sobredito. E além disso cada Scrivão dos ditos auditorios terá seu caderno, no qual assentará todo o dinheiro e penhores, que ao dito Thesoureiro for mandado entregar no Juizo, de que for Scrivão, com todas as declarações acima ditas, para em todo tempo se saber, assi pelos assentos dos ditos Scrivães, como pelo livro da receita do Thesoureiro, todo o que lhe assi for entregue para mais segurança das partes. E as taes quantias e penhores não poderão ser postos, nem depositados em mão de outra alguma pessoa. E sendo-o, a pessoa, que em outra mão depositar, não ficará desobrigada de fazer o tal deposito, antes será constrangida a depositar outra vez na mão do dito Thesoureiro. E o Scrivão de qualquer Juizo, que screver auto de deposito, que nelle seja mandado depositar, feito em mão de outra pessoa, ou receber certidão delle, para a ajuntar aos autos, ou para ter em seu poder, pola primeira vez que nisso for comprehendido, será suspenso de seu Officio até nossa mercê, e pola segunda vez o perderá sem remissão. E o Julgador, que o tal deposito mandar fazer, ou admittir em outra pessoa, será outrosi suspenso até nossa mercê. E além disso assi o Scrivão, como o Julgador, pagarão ás partes toda a perda e dano, que dahi se lhes causar.` },
        { id: 'of1-txxviii-2', number: '2', text: `E assi mandamos, que seja entregue e carregado em receita ao dito Thesoureiro pelo modo sobredito o dinheiro da condenação das partes nos ditos Juízos e sportulas dos Julgadores delles, até se dar ás pessoas, a que pertencer. E assi todo o dinheiro das condenações applicadas à Redempção dos Captivos, até ser entregue ao Thesoureiro da dita Redempção, não o podendo elle logo receber. E o dito Thesoureiro dos depositos haverá todos os privilegios e liberdades concedidas aos Officiaes da Corte.` },
      ],
    },
    {
      id: 'titulo-xxix',
      title: `XXIX. Do Scrivão das fianças da Corte`,
      type: 'articles',
      articles: [
        { id: 'of1-txxix-preambulo', number: 'Preâmbulo', text: `O Scrivão das fianças da Corte em princípio de cada hum anno fará hum livro, em que registrará os Alvarás de fiança, e de reformações de mais tempo, que as partes houverem o dito anno, e instrumentos de fianças, sentenças e perdões, que as partes presentarem de seus livramentos. O qual livro será assinado nas folhas pelo Juiz das fianças, segundo fórma de nossas Ordenações. E screvendo nelle sem ser assinado, incorrerá na pena das ditas Ordenações. E no princípio do dito livro fará hum Repertorio per alphabeto, para pôr nelle os nomes das partes, que as fianças derem.` },
        { id: 'of1-txxix-1', number: '1', text: `E no dito livro registrará os ditos Alvarás de verbo ad verbum, dando fé no registro de como são assinados per Nós, passados pela Chancellaria, com declaração do dia, em que os registrou. E quando os Alvarás forem scriptos nas costas das petições, trasladará as ditas petições e portarias, declarando per quem são assinadas. E levará do registro e certidão, que ha de fazer nas costas dos Alvarás, de como ficão registrados e as fianças dadas, oitenta réis, ora os ditos Alvarás e petições sejam grandes, ora pequenos. E não dará certidão de como fica feito o dito registro, sem a fiança ficar primeiro registrada no livro, e o instrumento de fiança em seu poder.` },
        { id: 'of1-txxix-2', number: '2', text: `E não tomará fiança alguma per si, e as partes as darão perante os Julgadores, que para isso tiverem poder e trarão publicos instrumentos das ditas fianças, tomadas e abonadas per autoridade de justiça. Porém quando o Regedor, ou algum dos Corregedores da Corte, ou Desembargadores da Casa da Supplicação mandarem ás partes, que dem fiança, e ao dito Scrivão, que lha tome, declarando-lhes os nomes dos fiadores, que ha de tomar, as tomará, como per cada hum delles lhe for mandado. E nos instrumentos das fianças irão estas clausulas, convém a saber: Que os fiadores se obrigam a responder por ellas na Corte perante o Juiz das Fianças, ou perante qualquer Julgador, perante quem o Procurador do Hospital de todos os Santos da cidade de Lisboa, ou quem disso pretender interesse, os quizer demandar, postoque ahi não sejam achados, e que renunciam Juizes de seu fôro, privilegios, que de Nós até então, ou ao diante tiverem, de qualquer qualidade que sejam. E dirá o Tabellião no dito instrumento: Que stipula e aceita a dita fiança, como pessoa publica, em nome do dito Hospital e das pessoas, que da dita fiança possam pretender interesse. E não sendo os instrumentos nesta fórma, o Scrivão os não receberá.` },
        { id: 'of1-txxix-3', number: '3', text: `E trazendo as partes os instrumentos das fianças na dita fórma, os registrará ao pé dos Alvarás, declarando os dias, em que lhe foram presentados, e os nomes dos Tabelliães, que os fizeram, e o lugar, dia, mez e anno, em que foram feitos, e as testemunhas, que presentes foram, e os nomes e alcunhas, e Officios dos fiadores e abonadores, e lugares, em que são moradores, e quantia, em que cada hum o fiou e abonou, e nome e Officio do Julgador, que a tomou. E declarará no dito assento, como o dito instrumento fica em seu poder, e o assinará de seu sinal, e levará de registrar o dito instrumento de fiança, ou de a tomar per mandado, como dito he, oitenta réis.` },
        { id: 'of1-txxix-4', number: '4', text: `E para os instrumentos de fiança se acharem mais brevemente, terá os instrumentos de cada hum anno encadernados, e lhes porá o numero das folhas, e no assento do registro declarará a quantas folhas do caderno stá registrado, e na margem do Alvará (quando no livro registrará Alvará de reformação) porá cota a quantas folhas, e em que livro stá o principal Alvará de fiança.` },
        { id: 'of1-txxix-5', number: '5', text: `Item, no dito livro registrará os nossos Alvarás, e do Regedor e Desembargadores, per que se der spaço aos condemnados para irem servir seus degredos, do qual registro não passará certidão, sem primeiro ser dada a fiança na fórma acima dita. E do registro dos Alvarás e certidões, que passar, levará quarenta réis, e do registro dos instrumentos das fianças oitenta réis.` },
        { id: 'of1-txxix-6', number: '6', text: `E quando as partes trouxerem sentenças, per que foram livres, ou condemnados, ou perdões dos casos, de que se livraram sobre fiança, ou dos degredos, em que foram condemnados, ou certidões de como stão presos pelos casos, de que tinham havido Alvarás de fiança, e suas fianças dadas, ou trouxerem certidões de como ficam servindo os degredos, e pedirem que sejam os fiadores desobrigados; o dito Scrivão não registrará as taes sentenças, perdões e certidões, nem desobrigará os fiadores sem mandado do Juiz das fianças, sob pena de perder o Officio, e de pagar para o dito Hospital outra tanta quantia, como for a fiança, que desobrigar, e pagar mais a perda e interesse ás partes. E a tal desobrigação, que sem mandado do dito Juiz fizer, será nenhuma. E quando as sentenças, perdões, ou certidões lhe forem presentadas, buscará no livro das fianças os Alvarás principaes, e os das reformações, e porá nelles per sua letra sua fé do tempo, em que os taes Alvarás foram dados, declarando o dia, mez e anno, e os mezes, ou tempos de termos e spaços, que per os ditos Alvarás foram dados, para se livrarem as partes dos casos conteúdos nas ditas sentenças, ou perdões, ou para irem servir os degredos, e trazerem certidões de como os ficavam servindo; e com essa sua fé e declaração enviará os que pedirem, que lhe sejam as fianças desobrigadas, com as ditas sentenças, perdões, ou certidões ao Juiz das fianças, para elle mandar o que for justiça. E o dito Juiz assinará no termo, que o Scrivão fizer, da desobrigação da tal fiança, para constar, que o fez per seu mandado.` },
        { id: 'of1-txxix-7', number: '7', text: `E mandando o Juiz das fianças registrar as ditas sentenças, perdões, ou certidões, e desobrigar os fiadores, as registrará ao pé da fiança, declarando como aos casos conteúdos no Alvará de fiança foi apresentada sentença de livramento, ou condenação, ou perdão, ou certidão de como stava preso, ou stava servindo o degredo, declarando o dia, mez e anno da sentença, perdão, ou certidão e o lugar, em que foi dada, e o Scrivão, per que foi feita, e o nome dos Julgadores, ou Capitães, per que as sentenças, perdões, ou certidões foram passadas; e de como o Juiz das fianças as mandou registrar e desobrigar os fiadores, fará Alvará nas costas da sentença, perdão, ou certidão, em nome do Juiz, de como havia por desobrigados os fiadores, que será assinado pelo dito Juiz. E o Scrivão do tal registro e fé, que der para o Juiz ver se mandará desobrigar os fiadores, como acima dito he, não levará mais que quarenta réis.` },
        { id: 'of1-txxix-8', number: '8', text: `Item, não levará busca de nenhuma das vezes, que buscar no livro os Alvarás de fiança e reformações, nem as fianças, quando as buscar a requerimento das partes, ou de seus fiadores, para desobrigar a fiança, ou para registrar Alvarás de reformações de mais tempo, ou instrumentos de reformações de fiança. Porém sendo-lhe requeridos para outros casos, ou requerendo-lhos outrem, levará busca nos casos, tempo e modo, que a levam os Tabelliães das notas, e outro tanto, como elles levam, salvo se for á instancia do nosso Procurador, ou do Promotor da Justiça, ou do Sollicitador do Hospital, porque a estes não levará busca. E porá as pagas do que levar nas certidões, e nos registros, que registrar, e nos Alvarás, per que o Juiz houver os fiadores por desobrigados, porá a paga do que levou por registrar a sentença, perdão, ou certidão do mesmo Alvará: o que assi fará, sob pena de perdimento do Officio, e de tornar á parte em tresdobro o que levar.` },
        { id: 'of1-txxix-9', number: '9', text: `E fazendo o Scrivão outra scriptura mais da acima declarada, convém a saber, se se processarem alguns feitos perante o dito Juiz, ou se passarem Cartas para requerer os fiadores, ou sentenças, que o dito Juiz der, ou fazendo outra qualquer scriptura, levará o que levam os Scrivães do Judicial per seu Regimento. E levando mais do que dito he, incorrerá na pena da Ordenação posta aos Scrivães, que levam mais do que lhe he ordenado.` },
        { id: 'of1-txxix-10', number: '10', text: `E as fianças, sobre que se livrarem as pessoas, que forem presas por trazer seda, serão registradas pelo dito Scrivão, e não poderão ser soltas, sem mostrarem certidão do dito Scrivão. E os Ouvidores dos feitos crimes das nossas Relações não despacharão os feitos das ditas pessoas, sem primeiro a elles serem juntas as ditas certidões.` },
        { id: 'of1-txxix-11', number: '11', text: `E os livros das fianças, que vierem das Ilhas, serão entregues ao dito Scrivão, e não a outro Official algum, ao qual os Corregedores das ditas Ilhas e Desembargadores, que a ellas forem, terão cuidado de os enviar. E vindo os ditos livros ao Provedor do Hospital, elle os mandará ao dito Scrivão, ficando-lhe caderno das fianças, que nelles vem, para se poder requerer a execução contra as pessoas, que no perdimento dellas incorrerem. E bem assi lhe será entregue o caderno, que em cada seis mezes he obrigado o Scrivão das fianças da Casa do Porto a lhe enviar, como se dirá no Titulo 47 do dito Scrivão.` },
        { id: 'of1-txxix-12', number: '12', text: `E mandamos, que as fianças, que se perderem em casos crimes, de que algumas pessoas se livrarem no Juizo de nossa Fazenda, se appliquem para o Hospital de todos os Santos da cidade de Lisboa. Pela qual fiança haverão as partes primeiro sua satisfação, se pretenderem nisso ter justiça.` },
      ],
    },
    {
      id: 'titulo-xxx',
      title: `XXX. Dos Porteiros da Chancellaria do Reino e da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-txxx-preambulo', number: 'Preâmbulo', text: `O Porteiro da Chancellaria do Reino irá cada hum dia à casa do Chanceller Mór pela manhã, ou à tarde, segundo per elle for ordenado, e perante elle sellará as Cartas; e como forem selladas, as meterá em hum sacco cerrado e sellado, e as levará a casa do Scrivão da Chancellaria, sem se desviar do caminho para outra parte, e assi as terá, sem abrir o sacco, até que o Scrivão e Recebedor da Chancellaria se assentem para as dar; e perante elles abrirá o sacco, e tirará as Cartas e Alvarás, hum e hum, e os en- tregará ao Scrivão, e depois de lhe pôr a paga, e o Recebedor ser della entregue, o Porteiro de sua mão as dará às partes, sem outrem tomar Carta alguma, senão elle. O qual chamará as partes, que o Scrivão disser, e depois que as Cartas todas forem dadas, o Porteiro porá diante de si as Cartas da arca da Chancellaria, que ficaram por dar dos outros dias, e as dará ao Scrivão pela dita maneira, se as partes ahi stiverem, e as que ficarem, tornal-as-ha à dita arca.` },
        { id: 'of1-txxx-1', number: '1', text: `E em quanto se derem as Cartas, se alguma pessoa quizer embargar alguma, o poderá fazer, e pagará o direito do embargo à Chancellaria, que são dez réis de cada embargo. E o Scrivão entregará a tal Carta com os embargos ao Porteiro, que a leve aos Officiaes, a que pertencer o despacho delles: e o Scrivão porá nas costas dos embargos o dia, mez e anno, em que foi embargada, e o Porteiro haverá de seu trabalho por os levar à mesa, onde pertencer o despacho (sem nisso haver mais processo), quarenta réis. E mandando-se dar vista às partes, ou fazendo-se outra mais diligencia, ou em caso, que os tomar a parte para os guardar, para quando a Carta, ou Provisão houver de passar pela Chancellaria, levará cem réis. E em nenhum caso tomará embargos, se não forem assinados pela parte, ou per seu bastante Procurador; e fazendo o contrario, ou passando a Carta, sem elle sair com os embargos, que tiver em seu poder, tornará o salario à parte, e lhe pagará todas as custas, perdas e damnos, que por elle receber.` },
        { id: 'of1-txxx-2', number: '2', text: `E será obrigado a fazer o que lhe for mandado pelo Chanceller Mór e Officiaes da Chancellaria, que a nosso serviço e a ella pertencer.` },
        { id: 'of1-txxx-3', number: '3', text: `E este Regimento guardará o Porteiro da Chancellaria da Casa da Supplicação nas sentenças e Cartas, que per ella passarem. E sendo embargadas na Chancellaria, as levará ao Julgador, que as assinou, para as despachar em Relação, se nella for dado o desembargo.` },
      ],
    },
  ],
};
